use vstd::prelude::*;

verus! {

spec fn rev_index(n: nat, j: nat) -> nat {
    // for j in 0..n, maps to the source index when reversing
    (n - 1 - j) as nat
}

spec fn reverse_seq(s: Seq<i32>) -> Seq<i32> {
    Seq::new(s.len(), |j: int| s[(s.len() - 1 - j) as int])
}

fn reverse(a: &Vec<i32>) -> (a_rev: Vec<i32>)
    ensures
        a_rev@ == reverse_seq(a@),
        a_rev@.len() == a@.len(),
{
    let n = a.len();
    let mut a_rev = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            n == a.len(),
            a_rev@.len() == (n - 1 - i) as nat,
            a_rev@ == Seq::new((n - 1 - i) as nat, |j: int| a@[((n - 1 - j) as nat) as int]),
    {
        a_rev.push(a[i]);
    }

    a_rev
}

} // verus!

